const fs = require('fs');

// We will create a writable stream that outputs to the console for this example
// In reality, you'd do: const logger = fs.createWriteStream('./access.log');
const logger = process.stdout; 

console.log("--- Server Logs ---");

// Writing data chunk by chunk
logger.write("User Alice logged in.\n");
logger.write("User Bob updated profile.\n");
logger.write("System backup started.\n");

// In a file stream, calling .end() closes the file safely.
// We can't call .end() on process.stdout, or we break the terminal!
// logger.end();

console.log("--- End Logs ---");
